package dev.codewitness.core.spi;

import java.util.List;
import java.util.Objects;

/**
 * A test case generated by CodeWitness.
 *
 * <p>Generated tests are ordinary tests in the project's own language: they are written into the
 * project's test sources, compiled and executed by the project's own build tool. Nothing about them
 * is special at runtime, which is what makes them reproducible by hand.
 *
 * @param className      identifier of the generated test in its language (a class name for Java, a
 *     module name for Python, a file stem for Go, Rust, JavaScript and TypeScript)
 * @param sourceCode     the generated source
 * @param testMethod     method to run when reproducing a specific counterexample, or {@code null}
 * @param requirementIds requirements the test targets
 * @param obligationIds  obligations the test discharges
 * @param description    what the test does
 * @param seed           random seed baked into the test, or {@code null} when deterministic
 * @param caseIndex      fixed case index for boundary cases, or {@code null}
 * @param checksInvariant {@code true} when the generated test actually asserts something about the
 *     requirement, that is when the scenario declared both an {@code observation} and an
 *     {@code invariant}. A test that only runs the declared steps asserts nothing, so it must never
 *     be counted as an experiment that discharged an obligation. The shorter constructor defaults
 *     this to {@code false}: a generator that forgets to set it makes its requirements
 *     {@code UNVERIFIED}, which is the safe direction to fail in.
 */
public record GeneratedTest(
        String className,
        String sourceCode,
        String testMethod,
        List<String> requirementIds,
        List<String> obligationIds,
        String description,
        Long seed,
        Integer caseIndex,
        boolean checksInvariant) {

    public GeneratedTest {
        Objects.requireNonNull(className, "className");
        Objects.requireNonNull(sourceCode, "sourceCode");
        requirementIds = List.copyOf(requirementIds == null ? List.of() : requirementIds);
        obligationIds = List.copyOf(obligationIds == null ? List.of() : obligationIds);
        description = description == null ? className : description;
    }

    /**
     * Builds a generated test that asserts nothing about the requirement.
     *
     * <p>Prefer the canonical constructor, which states explicitly whether the test checks an
     * invariant. This overload exists for tests and for callers that genuinely have no oracle.
     */
    public GeneratedTest(
            String className,
            String sourceCode,
            String testMethod,
            List<String> requirementIds,
            List<String> obligationIds,
            String description,
            Long seed,
            Integer caseIndex) {
        this(className, sourceCode, testMethod, requirementIds, obligationIds, description, seed, caseIndex, false);
    }

    /** @return a path for this test relative to a source root, used for artifacts and Java sources. */
    public String relativePath() {
        return className.replace('.', '/') + ".java";
    }

    /** @return the simple class name. */
    public String simpleName() {
        int index = className.lastIndexOf('.');
        return index < 0 ? className : className.substring(index + 1);
    }
}
